# bliss-banner.sh — Bliss launch sticker: truecolor half-block anime art,
# one random design per interactive shell, printed at most ONCE per terminal
# tab (even if several rc files or nested shells source it). Works with zsh,
# bash and POSIX sh. Opt out at runtime: FLUX_NO_BANNER=1
bliss_banner_art() {
  # zsh: empty glob must not abort the function.
  if [ -n "${ZSH_VERSION:-}" ]; then
    setopt localoptions nullglob nonomatch 2>/dev/null || true
  fi
  _bb_dir="${HOME:-/root}/.config/bliss/banner"
  [ -d "$_bb_dir" ] || return 0
  _bb_list=""
  _bb_n=0
  for _bb_f in "$_bb_dir"/*.txt; do
    [ -f "$_bb_f" ] || continue
    _bb_list="$_bb_list$_bb_f
"
    _bb_n=$((_bb_n + 1))
  done
  [ "$_bb_n" -gt 0 ] || return 0
  if [ -n "${RANDOM:-}" ]; then
    _bb_i=$(( (RANDOM % _bb_n) + 1 ))
  else
    _bb_i="$(awk -v n="$_bb_n" 'BEGIN { srand(); print int(rand() * n) + 1 }' 2>/dev/null || echo 1)"
  fi
  _bb_pick="$(printf '%s' "$_bb_list" | sed -n "${_bb_i}p")"
  [ -f "$_bb_pick" ] || return 0
  # The designs carry literal \033 truecolor escapes -> rendered with printf %b.
  if grep -q '\\033' "$_bb_pick" 2>/dev/null; then
    printf '%b\n' "$(cat "$_bb_pick" 2>/dev/null || true)"
  else
    cat "$_bb_pick" 2>/dev/null || true
  fi
  unset _bb_dir _bb_list _bb_n _bb_f _bb_i _bb_pick
}
bliss_banner() {
  [ "${FLUX_NO_BANNER:-0}" = "1" ] && return 0
  [ -z "${_BLISS_BANNER_SHOWN:-}" ] || return 0
  case $- in
    *i*) ;;
    *) return 0 ;;
  esac
  # Once per terminal tab. The exported guard covers nested shells that
  # inherit the environment. A pty-keyed marker (pty node ctime + a short
  # time window as fallback) covers shells that lose the environment
  # (`su -` chains, re-sourced rc files in a fresh process): nested shells in
  # the SAME tab never reprint, while a NEW tab - even one that reuses the
  # same pty number quickly - gets its own sticker.
  _bb_skip=0
  _bb_tty="$(tty 2>/dev/null || true)"
  case "$_bb_tty" in
    /dev/*)
      _bb_mark="${TMPDIR:-/tmp}/.bliss-banner$(printf '%s' "$_bb_tty" | tr -d ' /')"
      _bb_now="$(date +%s 2>/dev/null || echo 0)"
      case "$_bb_now" in ''|*[!0-9]*) _bb_now=0 ;; esac
      # Sub-second pty node ctime: exact per-tab identity when the platform
      # reports it; otherwise a tight open-chain window dedupes nested shells.
      _bb_ct="$(stat -c %.9Z "$_bb_tty" 2>/dev/null || echo '')"
      case "$_bb_ct" in
        *.*) case "$_bb_ct" in *[!0-9.]*) _bb_ct="" ;; esac ;;
        *) _bb_ct="" ;;
      esac
      if [ -f "$_bb_mark" ]; then
        _bb_prev="$(sed -n 1p "$_bb_mark" 2>/dev/null || echo 0)"
        _bb_ct_prev="$(sed -n 2p "$_bb_mark" 2>/dev/null || echo '')"
        case "$_bb_prev" in ''|*[!0-9]*) _bb_prev=0 ;; esac
        if [ -n "$_bb_ct" ] && [ "$_bb_ct" = "$_bb_ct_prev" ]; then
          _bb_skip=1
        elif [ -z "$_bb_ct" ] && [ "$_bb_now" -gt 0 ] && [ "$_bb_prev" -gt 0 ] && [ $((_bb_now - _bb_prev)) -lt 10 ]; then
          _bb_skip=1
        fi
      fi
      if [ "$_bb_skip" = "0" ]; then
        printf '%s\n%s\n' "$_bb_now" "$_bb_ct" > "$_bb_mark" 2>/dev/null || true
      fi
      ;;
  esac
  if [ "$_bb_skip" = "1" ]; then
    export _BLISS_BANNER_SHOWN=1
    unset _bb_skip _bb_tty _bb_mark _bb_now _bb_prev _bb_ct _bb_ct_prev
    return 0
  fi
  export _BLISS_BANNER_SHOWN=1
  bliss_banner_art
  # Header: exactly one line, "bliss@<id>" (distro id only). ID= from
  # /etc/os-release; fallbacks: first word of PRETTY_NAME, then "linux".
  _bb_fid=""
  if [ -r /etc/os-release ]; then
    _bb_fid="$(sed -n 's/^ID=//p' /etc/os-release 2>/dev/null | head -n 1 | tr -d '"' | tr '[:upper:]' '[:lower:]')"
    if [ -z "$_bb_fid" ]; then
      _bb_fid="$(sed -n 's/^PRETTY_NAME=//p' /etc/os-release 2>/dev/null | head -n 1 | tr -d '"' | awk '{print $1}' | tr '[:upper:]' '[:lower:]')"
    fi
  fi
  [ -n "$_bb_fid" ] || _bb_fid="linux"
  printf '%s\n' "bliss@$_bb_fid"
  unset _bb_fid _bb_skip _bb_tty _bb_mark
}
bliss_banner
FB_SH
    _fneed=0
  fi
  unset _fbdir _fb _fneed _fbrev
  # Existing .zshrc: dedupe old sticker/apply appends, keep exactly one of each.
  if [ -f "$_home/.zshrc" ]; then
    awk '/banner\.sh/ { if (b++) next } /appearance-apply\.sh/ { if (a++) next } { print }' \
      "$_home/.zshrc" > "$_home/.zshrc.bliss.$$" 2>/dev/null && \
      mv -f "$_home/.zshrc.bliss.$$" "$_home/.zshrc" 2>/dev/null || rm -f "$_home/.zshrc.bliss.$$" 2>/dev/null || true
    if ! grep -q 'bliss/banner.sh' "$_home/.zshrc" 2>/dev/null; then
      {
        printf '\n# Bliss launch sticker (random truecolor anime banner; opt out FLUX_NO_BANNER=1)\n'
        printf '[ -r "$HOME/.config/bliss/banner.sh" ] && . "$HOME/.config/bliss/banner.sh"\n'
      } >> "$_home/.zshrc" 2>/dev/null || true
    fi
  fi
  # Bash login wiring (bash sessions get the same sticker).
  if [ ! -f "$_home/.bashrc" ]; then
    printf '%s\n' '# Bliss bash profile' 'export PATH="$HOME/.local/bin:$PATH"' > "$_home/.bashrc" 2>/dev/null || true
  fi
  if [ -f "$_home/.bashrc" ] && ! grep -q 'bliss/banner.sh' "$_home/.bashrc" 2>/dev/null; then
    {
      printf '\n# Bliss launch sticker (random truecolor anime banner; opt out FLUX_NO_BANNER=1)\n'
      printf '[ -r "$HOME/.config/bliss/banner.sh" ] && . "$HOME/.config/bliss/banner.sh"\n'
    } >> "$_home/.bashrc" 2>/dev/null || true
  fi
  if [ -d "$_home" ] && [ ! -f "$_home/.bash_profile" ]; then
    {
      printf '%s\n' '[ -f "$HOME/.profile" ] && . "$HOME/.profile"'
      printf '%s\n' '[ -f "$HOME/.bashrc" ] && . "$HOME/.bashrc"'
    } > "$_home/.bash_profile" 2>/dev/null || true
  fi
  if [ ! -f "$_home/.zprofile" ]; then
    printf '%s\n' '[[ -o interactive ]] || { [ -f "$HOME/.zshrc" ] && . "$HOME/.zshrc"; }' \
      > "$_home/.zprofile"
  fi
  if [ -x "$FLUX_CHROOT/bin/zsh" ] && [ -f "$FLUX_CHROOT/etc/passwd" ] && \
     grep -q '^flux:' "$FLUX_CHROOT/etc/passwd" && \
     ! grep -q '^flux:.*zsh$' "$FLUX_CHROOT/etc/passwd"; then
    sed -i 's|^\(flux:[^:]*:[^:]*:[^:]*:[^:]*:[^:]*\):.*|\1:/bin/zsh|' \
      "$FLUX_CHROOT/etc/passwd" 2>/dev/null || true
  fi
  chown --reference="$_home" "$_home/.zshrc" "$_home/.zprofile" \
    "$_home/.bashrc" "$_home/.bash_profile" \
    "$_home/.oh-my-zsh/custom/themes/bliss.zsh-theme" 2>/dev/null || true
  if [ -d "$_home/.config/bliss" ]; then
    chown -R --reference="$_home" "$_home/.config/bliss" 2>/dev/null || true
  fi
  # Bliss Linux appearance: re-apply the app-staged config when it changed.
  # Runs inside the chroot (guest tools + guest paths); the script is
  # hash-guarded, so repeated logins are cheap no-ops when nothing changed.
  if [ -r "$_home/.config/bliss/appearance-apply.sh" ]; then
    "$BB" chroot "$FLUX_CHROOT" /bin/sh -c \
      'export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin; \
       FOLIO_APPLY_HOME=/home/flux /bin/sh /home/flux/.config/bliss/appearance-apply.sh \
       >/dev/null 2>&1 || true' >/dev/null 2>&1 || true
  fi
  # Root parity: /root carries the SAME sticker + art set as flux (copied, so
  # app-selected quality/NSFW follows), and the same rc dedupe so duplicated
  # old source lines can never flood the tab again.
  if [ "$USER_NAME" = "root" ] && [ "$_home" != "$FLUX_CHROOT/home/flux" ]; then
    _fsrc="$FLUX_CHROOT/home/flux/.config/bliss"
    _rdir="$FLUX_CHROOT/root/.config/bliss"
    if [ -d "$_fsrc/banner" ]; then
      mkdir -p "$_rdir/banner" 2>/dev/null || true
      cp -f "$_fsrc/banner.sh" "$_rdir/banner.sh" 2>/dev/null || true
      cp -f "$_fsrc/banner"/*.txt "$_rdir/banner/" 2>/dev/null || true
      cp -f "$_fsrc/banner/.banner-rev" "$_rdir/banner/.banner-rev" 2>/dev/null || true
      chown -R --reference="$_home" "$_rdir" 2>/dev/null || true
    fi
    for _rc in "$_home/.zshrc" "$_home/.bashrc" "$_home/.profile" "$_home/.bash_profile"; do
      [ -f "$_rc" ] || continue
      awk '/banner\.sh/ { if (b++) next } /appearance-apply\.sh/ { if (a++) next } { print }' \
        "$_rc" > "$_rc.bliss.$$" 2>/dev/null && mv -f "$_rc.bliss.$$" "$_rc" 2>/dev/null || \
        rm -f "$_rc.bliss.$$" 2>/dev/null || true
    done
    if [ -f "$_home/.zshrc" ] && ! grep -q 'bliss/banner.sh' "$_home/.zshrc" 2>/dev/null; then
      {
        printf '\n# Bliss launch sticker (random truecolor anime banner; opt out FLUX_NO_BANNER=1)\n'
        printf '[ -r "$HOME/.config/bliss/banner.sh" ] && . "$HOME/.config/bliss/banner.sh"\n'
      } >> "$_home/.zshrc" 2>/dev/null || true
    fi
    if [ -f "$_home/.bashrc" ] && ! grep -q 'bliss/banner.sh' "$_home/.bashrc" 2>/dev/null; then
      {
        printf '\n# Bliss launch sticker (random truecolor anime banner; opt out FLUX_NO_BANNER=1)\n'
        printf '[ -r "$HOME/.config/bliss/banner.sh" ] && . "$HOME/.config/bliss/banner.sh"\n'
      } >> "$_home/.bashrc" 2>/dev/null || true
    fi
    unset _fsrc _rdir _rc
  fi
}

guest_login() {
  ensure_flux_zsh_profile
  LOGIN_SHELL="$(resolve_login_shell "${LOGIN_SHELL:-zsh}")"
  # Optional project cwd (workspace shell). Path must not contain single quotes.
  _cd=""
  if [ -n "${LOGIN_WORKDIR:-}" ]; then
    case "$LOGIN_WORKDIR" in
      *"'"*) die "workdir must not contain single quotes" ;;
    esac
    _cd="cd '$LOGIN_WORKDIR' 2>/dev/null || true; "
  fi
  case "$USER_NAME" in
    root)
      case "$LOGIN_SHELL" in
        zsh)
          if [ -n "$_cd" ]; then
            guest_chroot_env /bin/zsh -c "${_cd}exec /bin/zsh -l"
          else
            guest_chroot_env /bin/zsh -l
          fi
          ;;
        sh|ash)
          # Alpine/Chimera minirootfs — resolver may return sh when bash/zsh missing
          if [ -n "$_cd" ]; then
            guest_chroot_env /bin/sh -c "${_cd}exec /bin/sh -l"
          else
            guest_chroot_env /bin/sh -l
          fi
          ;;
        bash|*)
          if [ -n "$_cd" ]; then
            guest_chroot_env /bin/bash --login -c "${_cd}exec /bin/bash --login"
          else
            guest_chroot_env /bin/bash --login
          fi
          ;;
      esac
      ;;
    flux|*)
      guest_login_user
      ;;
  esac
}

# Non-interactive: one shell string as USER_NAME (single chroot + one su layer).
# Host-encode to base64 then guest_b64 — avoids double-quote/$/` breakage (G3).
guest_sh() {
  _cmd="$1"
  _b64=""
  if command -v base64 >/dev/null 2>&1; then
    _b64=$(printf '%s' "$_cmd" | base64 | tr -d '\n')
  elif [ -n "$BB" ]; then
    _b64=$(printf '%s' "$_cmd" | $BB base64 2>/dev/null | tr -d '\n')
  fi
  if [ -n "$_b64" ]; then
    guest_b64 "$_b64"
    return
  fi
  # Fallback only if host has no base64 (should not happen on Android root)
  # Prefer bash when present; Alpine minirootfs only has /bin/sh until bootstrap.
  _gshell=/bin/sh
  [ -x "${FLUX_CHROOT:-}/bin/bash" ] || [ -x /bin/bash ] && _gshell=/bin/bash
  if [ "$USER_NAME" = "root" ]; then
    guest_chroot_env "$_gshell" -c "$_cmd"
  else
    guest_as_user "$_gshell" -c "$_cmd"
  fi
}

# Argv-preserving exec (root: chroot + binary; flux: su -c with quoted argv).
guest_exec() {
  if [ "$#" -lt 1 ]; then
    die "exec requires CMD"
  fi
  if [ "$USER_NAME" = "root" ]; then
    guest_chroot_env "$@"
  else
    _joined=$(quote_argv "$@")
    _eshell=/bin/bash
    guest_bin_exists bash || _eshell=/bin/sh
    guest_as_user "$_eshell" -c "exec $_joined"
  fi
}

# Base64 payload → guest shell as USER_NAME (Kotlin / RootShell path).
# Absolute /usr/bin/base64 — never depend on guest PATH for decode bootstrap.
# TTY-safe: decode to temp script then run FILE (do NOT pipe into bash — that steals stdin
# and breaks TUI tools needing /dev/tty: bubbletea, grok, claude, opencode).
# Prefers /bin/bash when present; falls back to /bin/sh for Alpine minirootfs.
guest_b64() {
  _b64="$1"
  [ -n "$_b64" ] || die "b64 requires payload"
  # alphabet-only payload — safe inside single quotes
  # \$ preserved for guest; host expands only ${_b64}
  _inner="_b='${_b64}'; _f=/tmp/.nc_b64_\$\$; { echo \$_b | /usr/bin/base64 -d 2>/dev/null || echo \$_b | /bin/base64 -d; } >\$_f || exit 2; if [ -x /bin/bash ]; then /bin/bash --noprofile --norc \$_f; else /bin/sh \$_f; fi; _e=\$?; rm -f \$_f; exit \$_e"
  if [ "$USER_NAME" = "root" ]; then
    # Outer bootstrap: sh always exists; inner script picks bash if available
    guest_chroot_env /bin/sh -c "$_inner"
  else
    guest_as_user /bin/sh -c "$_inner"
  fi
}

parse_common_flags() {
  while [ "$#" -gt 0 ]; do
    case "$1" in
      --user)
        [ "$#" -ge 2 ] || die "--user needs value"
        USER_NAME="$2"
        shift 2
        ;;
      --shell)
        [ "$#" -ge 2 ] || die "--shell needs value"
        LOGIN_SHELL="$2"
        shift 2
        ;;
      --x11)
        WANT_X11=1
        shift
        ;;
      --)
        shift
        REMAINING_ARGS="$@"
        return 0
        ;;
      -*)
        die "unknown flag: $1"
        ;;
      *)
        REMAINING_ARGS="$@"
        return 0
        ;;
    esac
  done
  REMAINING_ARGS=""
}

# --- main ---
[ "$#" -ge 1 ] || usage
MODE="$1"
shift

case "$MODE" in
  version|-V|--version)
    echo "$VERSION_STR"
    exit 0
    ;;
  mount|login|sh|exec|b64) ;;
  -h|--help|help) usage ;;
  *) die "unknown mode: $MODE" ;;
esac

require_root
resolve_bb || die "root-capable busybox not found"

# Flag parse: collect until -- or end; modes sh/exec/b64 need --
REMAINING_ARGS=""
WANT_X11=0
USER_NAME="flux"
LOGIN_SHELL="${FLUX_SHELL:-zsh}"

case "$MODE" in
  mount)
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --x11) WANT_X11=1; shift ;;
        *) die "mount: unknown arg $1" ;;
      esac
    done
    ensure_mounts
    exit 0
    ;;
  login)
    LOGIN_WORKDIR=""
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --user)
          [ "$#" -ge 2 ] || die "--user needs value"
          USER_NAME="$2"; shift 2
          ;;
        --shell)
          [ "$#" -ge 2 ] || die "--shell needs value"
          LOGIN_SHELL="$2"; shift 2
          ;;
        --workdir)
          [ "$#" -ge 2 ] || die "--workdir needs value"
          LOGIN_WORKDIR="$2"; shift 2
          ;;
        --x11) WANT_X11=1; shift ;;
        *) die "login: unknown arg $1" ;;
      esac
    done
    case "$USER_NAME" in root|flux) ;; *) die "user must be flux|root" ;; esac
    ensure_mounts
    guest_login
    ;;
  sh)
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --user)
          [ "$#" -ge 2 ] || die "--user needs value"
          USER_NAME="$2"; shift 2
          ;;
        --x11) WANT_X11=1; shift ;;
        --) shift; break ;;
        *)
          # allow bare string without -- for convenience
          break
          ;;
      esac
    done
    case "$USER_NAME" in root|flux) ;; *) die "user must be flux|root" ;; esac
    [ "$#" -ge 1 ] || die "sh requires a shell string"
    # Join remaining as one command string (caller may pass one quoted arg)
    CMD_STR="$*"
    ensure_mounts
    guest_sh "$CMD_STR"
    ;;
  exec)
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --user)
          [ "$#" -ge 2 ] || die "--user needs value"
          USER_NAME="$2"; shift 2
          ;;
        --x11) WANT_X11=1; shift ;;
        --) shift; break ;;
        *) break ;;
      esac
    done
    case "$USER_NAME" in root|flux) ;; *) die "user must be flux|root" ;; esac
    [ "$#" -ge 1 ] || die "exec requires CMD"
    ensure_mounts
    guest_exec "$@"
    ;;
  b64)
    while [ "$#" -gt 0 ]; do
      case "$1" in
        --user)
          [ "$#" -ge 2 ] || die "--user needs value"
          USER_NAME="$2"; shift 2
          ;;
        --x11) WANT_X11=1; shift ;;
        --) shift; break ;;
        *) break ;;
      esac
    done
    case "$USER_NAME" in root|flux) ;; *) die "user must be flux|root" ;; esac
    [ "$#" -ge 1 ] || die "b64 requires payload"
    B64_PAYLOAD="$1"
    ensure_mounts
    guest_b64 "$B64_PAYLOAD"
    ;;
esac
